import React, { useState } from "react";
import data from "./Details";
import { Element } from "react-scroll";
import {
  Tabs,
  TabsHeader,
  TabsBody,
  Tab,
  TabPanel,
} from "@material-tailwind/react";
import "../App.css";

const Projects = () => {
  const [activeTab, setActiveTab] = useState("reactjs");

  return (
    <Element id="projectsPage" name="projectsPage" className="relative">
      <div className="py-16 text-white ">
        <section className="flex flex-col w-full px-4 my-5 md:px-10 lg:px-24">
          {/* Header */}
          <div className="flex justify-center">
            <h1 className="text-3xl font-bold tracking-wide text-orange-500 md:text-4xl">
              My Projects
            </h1>
          </div>

          {/* Tabs for Categories */}
          <Tabs
            value={activeTab}
            className="w-full mt-8"
          >
            {/* Tab Headers */}
            <TabsHeader className="flex justify-center overflow-x-auto">
              {data.map(({ label, value }) => (
                <Tab
                  key={value}
                  value={value}
                  onClick={() => setActiveTab(value)}
                  className={`${
                    activeTab === value
                      ? "text-orange-500 font-bold border-b-4 border-orange-500"
                      : "text-gray-400"
                  } text-sm md:text-lg px-4 md:px-6 pb-2 whitespace-nowrap transition-all duration-300 ease-in-out`}
                >
                  {label}
                </Tab>
              ))}
            </TabsHeader>

            {/* Tab Panels */}
            <TabsBody>
              {data.map(({ value, projects }) => (
                <TabPanel key={value} value={value}>
                  {/* Display multiple projects under each tab */}
                  <div className="grid grid-cols-1 gap-6 mt-8 lg:grid-cols-2 lg:gap-10">
                    {projects.map((project, index) => (
                      <div
                        key={index}
                        className="flex flex-col items-center p-4 space-y-6 bg-gray-600 rounded-lg shadow-lg md:flex-row md:p-6 md:space-y-0 md:space-x-6"
                      >
                        {/* Project Image */}
                        <div className="w-full md:w-1/2 h-[200px] md:h-[300px] flex-shrink-0">
                          <img
                            src={project.imgSrc}
                            alt={project.title}
                            className="object-cover w-full h-full rounded-lg"
                          />
                        </div>

                        {/* Project Details */}
                        <div className="w-full space-y-4 text-gray-300 md:w-1/2">
                          {/* Project Title */}
                          <h3 className="text-xl font-bold text-orange-400 md:text-2xl">
                            {project.title}
                          </h3>

                          {/* Project Description */}
                          <p className="text-sm md:text-base">{project.desc}</p>

                          {/* Tech Stack */}
                          <h4 className="text-base font-bold text-white md:text-lg">
                            Tech Stack:
                          </h4>
                          <ul className="ml-5 text-sm list-disc md:text-base">
                            {project.techStack.map((tech, index) => (
                              <li key={index} className="text-gray-400">
                                {tech}
                              </li>
                            ))}
                          </ul>
                        </div>
                      </div>
                    ))}
                  </div>
                </TabPanel>
              ))}
            </TabsBody>
          </Tabs>
        </section>
      </div>
    </Element>
  );
};

export default Projects;
