import React, { useState, useEffect, useMemo } from "react";
import { Link } from "react-scroll";
import Hamburger from "./Burger";
import "./Burger.css";

function Sidebar() {
  const sections = useMemo(
    () => [
      { id: "homePage", name: "Home" },
      { id: "cert", name: "Certificates" },
      { id: "projectsPage", name: "Projects" },
      { id: "aboutMe", name: "About me" },
    ],
    []
  );

  // Set default active section to -1 (no section is active initially)
  const [activeSection, setActiveSection] = useState(-1);

  const handleSectionChange = (index) => {
    setActiveSection(index);
  };

  useEffect(() => {
    const handleScroll = () => {
      const sectionOffsets = sections.map(
        (section) => document.getElementById(section.id)?.offsetTop
      );

      const scrollPosition = window.scrollY + 160; // Adjust this value based on your design

      const activeIndex = sectionOffsets.findIndex(
        (offset, index) =>
          offset <= scrollPosition &&
          (sectionOffsets[index + 1] || Infinity) > scrollPosition
      );

      setActiveSection(activeIndex !== -1 ? activeIndex : -1);
    };

    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, [sections]);

  return (
    <header>
      <div className="flex fixed justify-between items-center h-24 text-white w-screen xs:h-[4em] bg-[#111827] z-[999] border-b-1 border-[#FFA500] md:shadow-md md:shadow-black shadow-md shadow-[#FFA500]">
        <div className="hidden md:flex md:ml-[4ch] lg:ml-[8ch] gap-10 items-center">
          <img
            src={process.env.PUBLIC_URL + "/logo.png"}
            alt="Company Logo"
            className="flex w-10 h-10 md:w-10 md:h-10"
          />
          <ul className="flex gap-4">
            {sections.map((section, index) => (
              <li
                key={section.id}
                onClick={() => handleSectionChange(index)}
                className={`nav-link relative px-2 py-1 cursor-pointer ${
                  activeSection === index ? "active-tab" : ""
                }`}
              >
                <Link
                  to={section.id}
                  spy={true}
                  smooth={true}
                  offset={-100}
                  duration={700}
                >
                  {section.name}
                </Link>
              </li>
            ))}
          </ul>
        </div>
        <div className="ml-6 md:hidden">
          <Hamburger initialValue={false} />
        </div>
      </div>
    </header>
  );
}

export default Sidebar;
