import React, { useState, useEffect } from "react";
import { Link } from "react-scroll";

function Hamburger({ initialValue }) {
  const [isChecked, setIsChecked] = useState(initialValue);
  const [activeIcon, setActiveIcon] = useState(null); // Default to null for no active icon initially

  const handleCheckboxChange = (event) => {
    setIsChecked(event.target.checked);
  };

  useEffect(() => {
    // Add any side effects related to `isChecked` if needed
  }, [isChecked]);

  const navLinks = [
    { desc: "Home", ids: "homePage" },
    { desc: "Certificates", ids: "cert" },
    { desc: "Projects", ids: "projectsPage" },
    { desc: "About me", ids: "aboutMe" },
  ];

  const handleIconClick = (index) => {
    setActiveIcon(index);
  };

  return (
    <div className="">
      <div
        onClick={() => setIsChecked(isChecked)}
        className={`relative z-[999] ${
          isChecked ? "text-gray-900" : "text-gray-100"
        } text-md md:hidden m-5`}
      >
        <label className="hamburger">
          <input
            type="checkbox"
            checked={isChecked}
            onChange={handleCheckboxChange}
          />
          <svg viewBox="0 0 32 32">
            <path
              className="line line-top-bottom"
              d="M27 10 13 10C10.8 10 9 8.2 9 6 9 3.5 10.8 2 13 2 15.2 2 17 3.8 17 6L17 26C17 28.2 18.8 30 21 30 23.2 30 25 28.2 25 26 25 23.8 23.2 22 21 22L7 22"
            ></path>
            <path className="line" d="M7 16 27 16"></path>
          </svg>
        </label>
      </div>

      <div
        className={`absolute w-2/3 h-screen bg-gradient-to-b from-[#111827] via-slate-600 to-gray-800 top-0 left-0 duration-200 shadow-md shadow-black md:hidden ${
          isChecked ? "left-0" : "left-[-100%]"
        }`}
      >
        <ul className="flex flex-col justify-center h-full gap-10 py-2 text-2xl text-right uppercase px-7">
          {navLinks.map((descData, index) => (
            <Link
              key={index}
              to={descData.ids}
              className="rounded-[50px]"
              spy={true}
              smooth={true}
              offset={-100}
              duration={700}
            >
              <li
                onClick={() => handleIconClick(index)}
                className={`hover:text-[#FFA500] relative px-2 py-1 border-b-2 ${
                  activeIcon === index ? "border-[#FFA500]" : "border-transparent"
                }`}
              >
                {descData.desc}
              </li>
            </Link>
          ))}
        </ul>
      </div>

      <div
        className={`fixed right-0 top-0 h-full bg-blur backdrop-blur-xl transition-all ${
          isChecked ? "opacity-80" : "hidden opacity-0 pointer-events-none"
        }`}
        style={{ width: "calc(100vw - 2/3 * 100vw)" }}
      ></div>
    </div>
  );
}

export default Hamburger;
