import React, { useState } from "react";
import { Carousel, IconButton } from "@material-tailwind/react";
import { Element } from "react-scroll";
import "../App.css";

const Certificates = () => {
  const [expandedDescId, setExpandedDescId] = useState(null);

  const handleToggleDescription = (id) => {
    setExpandedDescId(expandedDescId === id ? null : id);
  };

  const portfolios = [
    {
      id: 1,
      src: process.env.PUBLIC_URL + "/2ndrunnerbestthesis.png",
      desc: "Our thesis, 'E-Chequer: A Smart Exam Checking Machine Using Image Processing Technique,' blends software and hardware seamlessly. This innovative system offers a user-friendly web interface for teachers to manage scores efficiently. It promises to revolutionize assessment processes, showcasing technology's potential to enhance learning outcomes. We were honored to receive the 2nd runner-up award for Best Thesis in Community Based Projects.",
      title: "Best Thesis in Community Based Projects 2ND RUNNER UP",
    },
    {
      id: 2,
      src: process.env.PUBLIC_URL + "/CSEprof.png",
      desc: "",
      title: "Civil Service Eligible (Professional Level)",
    },
    {
      id: 3,
      src: process.env.PUBLIC_URL + "/dataAnalProf.png",
      desc: "",
      title: "Google Data Analytics (Professional Cert)",
    },
    {
      id: 4,
      src: process.env.PUBLIC_URL + "/googlemarketing.png",
      desc: "",
      title: "Fundamentals of Digital Marketing",
    },
    {
      id: 5,
      src: process.env.PUBLIC_URL + "/htmlcss.jpg",
      desc: "",
      title: "HTML And CSS",
    },
    {
      id: 6,
      src: process.env.PUBLIC_URL + "/solidfoundhtmlcss.jpg",
      desc: "",
      title: "Foundational HTML and CSS",
    },
    {
      id: 7,
      src: process.env.PUBLIC_URL + "/webdesign.jpeg",
      desc: "",
      title: "Web Design",
    },
    {
      id: 8,
      src: process.env.PUBLIC_URL + "/programmingFundpythong.jpg",
      desc: "",
      title: "Programming: Fundamentals of Python Programming",
    },
    {
      id: 9,
      src: process.env.PUBLIC_URL + "/cybersec.png",
      desc: "",
      title: "Intro to Cyber Security Webinar",
    },
    {
      id: 10,
      src: process.env.PUBLIC_URL + "/codecamp.jpg",
      desc: "",
      title: "Responsive Web (CodeCamp)",
    },
  ];

  const renderDescription = (desc, id) => {
    const isExpanded = expandedDescId === id;
    const previewText = desc.length > 150 ? `${desc.slice(0, 150)}...` : desc;

    return (
      <div>
        <div className="font-light text-justify text-md lg:text-lg">
          {isExpanded ? desc : previewText}
        </div>
        {desc.length > 150 && (
          <button
            onClick={() => handleToggleDescription(id)}
            className="mt-2 text-sm text-orange-500"
          >
            {isExpanded ? "See Less" : "See More"}
          </button>
        )}
      </div>
    );
  };

  return (
    <Element name="cert" className="relative">
      <div className="bg-gradient-to-b from-[#111827] to-gray-700 p-5 sm:p-10 lg:p-15 lg:pb-44 clip-path-triangle">
        <Carousel
          prevArrow={({ handlePrev }) => (
            <IconButton
              variant="text"
              color="white"
              size="lg"
              onClick={handlePrev}
              className="!absolute top-2/3 left-1 -translate-y-2/3 z-[998]"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
                strokeWidth={2}
                stroke="currentColor"
                className="w-6 h-6 text-orange-500"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M10.5 19.5L3 12m0 0l7.5-7.5M3 12h18"
                />
              </svg>
            </IconButton>
          )}
          nextArrow={({ handleNext }) => (
            <IconButton
              variant="text"
              color="white"
              size="lg"
              onClick={handleNext}
              className="!absolute top-2/3 right-1 -translate-y-2/3 z-[998]"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
                strokeWidth={2}
                stroke="currentColor"
                className="w-6 h-6 text-orange-500"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"
                />
              </svg>
            </IconButton>
          )}
          className="rounded-xl"
          navigation={({ setActiveIndex, activeIndex, length }) => (
            <div className="absolute z-50 flex gap-1 bottom-2 left-2/4 -translate-x-2/4 lg:gap-2">
              {new Array(length).fill("").map((_, i) => (
                <span
                  key={i}
                  className={`block h-1  rounded-2xl cursor-pointer transition-all ${
                    activeIndex === i ? "w-8 bg-orange-500" : "w-4 bg-white/50"
                  }`}
                  onClick={() => setActiveIndex(i)}
                />
              ))}
            </div>
          )}
        >
          {portfolios.map(({ id, src, desc, title }) => (
            <div
              key={id}
              className="grid items-center justify-center gap-4 p-6 lg:grid-cols-2 lg:gap-6 lg:p-24"
            >
              <div className="flex justify-center col-span-1">
                <img
                  src={src}
                  alt={id}
                  className="rounded-lg shadow-lg object-cover max-w-[100%] h-[300px] w-full sm:w-[400px] md:w-[500px] lg:h-[400px]"
                />
              </div>
              <div className="flex flex-col justify-center">
                <h1 className="mb-2 text-xl font-bold text-center text-white uppercase lg:text-2x">
                  {title}
                </h1>
                <div className="text-white">{renderDescription(desc, id)}</div>
              </div>
            </div>
          ))}
        </Carousel>
      </div>
    </Element>
  );
};

export default Certificates;
